//! Motorcomm YT921x Gigabit Ethernet switch family register definitions.
//!
//! Generated by `tools/generate.py` from `yt921x.yaml`. Do not edit.
//!
//! A register is a `u32` address constant, or a `const fn` taking the index
//! when the register is an array. A field is a [`Field`] constant named
//! `<REGISTER>_<FIELD>`, or a `const fn` taking the index for array fields.
//! Enumerated values are plain `u32` constants named
//! `<REGISTER>_<FIELD>_<VALUE>`.

/// Position of a bit field inside a register of one or more 32-bit words.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Field {
    /// Lowest bit of the field, counted from bit 0 of the first word.
    pub lsb: u8,
    /// Number of bits.
    pub width: u8,
}

impl Field {
    /// Index of the 32-bit word that holds the lowest bit.
    pub const fn word(self) -> usize {
        (self.lsb / 32) as usize
    }

    /// Shift of the field inside its word.
    pub const fn shift(self) -> u32 {
        (self.lsb % 32) as u32
    }

    /// Mask of the field inside its word. Bits that fall into the next
    /// word are cut off; use [`Field::get_words`] for such fields.
    pub const fn mask(self) -> u32 {
        ((((1u64 << self.width) - 1) << self.shift()) & 0xffff_ffff) as u32
    }

    /// Extract the field from the value of its word.
    pub const fn get(self, word: u32) -> u32 {
        (word & self.mask()) >> self.shift()
    }

    /// Shift a value into the position of the field inside its word.
    pub const fn prep(self, value: u32) -> u32 {
        (value << self.shift()) & self.mask()
    }

    /// Replace the field in the value of its word.
    pub const fn set(self, word: u32, value: u32) -> u32 {
        (word & !self.mask()) | self.prep(value)
    }

    /// Extract a field of up to 64 bits from a register held as words.
    pub fn get_words(self, words: &[u32]) -> u64 {
        let mut v = 0u64;
        for i in 0..self.width as usize {
            let b = self.lsb as usize + i;
            v |= (((words[b / 32] >> (b % 32)) & 1) as u64) << i;
        }
        v
    }

    /// Write a field of up to 64 bits into a register held as words.
    pub fn set_words(self, words: &mut [u32], value: u64) {
        for i in 0..self.width as usize {
            let b = self.lsb as usize + i;
            let bit = 1u32 << (b % 32);
            if (value >> i) & 1 != 0 {
                words[b / 32] |= bit;
            } else {
                words[b / 32] &= !bit;
            }
        }
    }
}

