pub const MIRROR_EGR_PORTS_ALL: Field = Field { lsb: 4, width: 11 };
/// Monitor port number.
pub const MIRROR_PORT: Field = Field { lsb: 0, width: 4 };

/// One part of the family and how to recognise it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Part {
    /// Part number.
    pub name: &'static str,
    /// Expected CHIP_ID.MAJOR.
    pub major: u16,
    /// Expected CHIP_MODE.MODE.
    pub mode: u8,
    /// Expected extended mode byte of the configuration byte store.
    pub extmode: u8,
    /// Ports with a built-in PHY, one bit per port.
    pub phy_ports: u16,
    /// Ports with xMII pins, one bit per port.
    pub xmii_ports: u16,
    /// Ports with a SerDes, one bit per port.
    pub serdes_ports: u16,
}

